function draw() {
    ctx.clearRect(0, 0, W, H);

    // ship
    ctx.fillStyle = '#0f0';
    ctx.beginPath();
    ctx.arc(ship.x, ship.y, ship.r, 0, Math.PI * 2);
    ctx.fill();

    // asteroids
